<script lang="ts">
import { type DateValue, getLocalTimeZone } from '@internationalized/date';
import {
  connect,
  machine,
  parse,
  type Props as DatePickerProps,
} from '@zag-js/date-picker';
import { normalizeProps, portal, useMachine } from '@zag-js/svelte';
import { omit } from 'lodash-es';

import { Icon } from '../icon';
import { InputStates } from '../input';
import {
  dateFromDateValueString,
  getDateValueString,
  parseDateValueString,
} from './date-value-string';
import { parseRelativeTime } from './parse-relative-time';
import type { RelativeTimeValue } from './relative-time';
import RelativeTimeIconButton from './relative-time-icon-button.svelte';
import RelativeTimeInput from './relative-time-input.svelte';

interface Props {
  value: string | undefined;
  disabled?: boolean;
  error?: string;
  isDateUnavailable?: DatePickerProps['isDateUnavailable'];
  onChange: (value: RelativeTimeValue) => void;
  applyTimeFilter: () => void;
}

let {
  value,
  disabled,
  error,
  isDateUnavailable,
  onChange,
  applyTimeFilter,
}: Props = $props();

const id = $props.id();

const timezone = getLocalTimeZone();
const relativeTime = $derived(value ? parseRelativeTime(value) : undefined);

let currentError = $derived<string | undefined>(error);

const resolvedValue = $derived.by(() => {
  if (!value) {
    return [];
  }

  if (relativeTime) {
    return [parse(relativeTime.toDate())];
  }

  const parsed = parseDateValueString(value);
  if (parsed.success) {
    return [parsed.date];
  }

  return [parse(new Date())];
});

const service = useMachine(machine, () => ({
  id,
  isDateUnavailable,
  positioning: {
    offset: { crossAxis: 190, mainAxis: -1 },
  },
  value: resolvedValue,
  disabled,

  onValueChange: (details) => {
    handleChange(details.valueAsString[0]);
  },

  format: (toFormat) => {
    if (value) {
      return value;
    }

    return getDateValueString(toFormat, timezone);
  },
}));

const api = $derived(connect(service, normalizeProps));

// omitting type, onbeforeinput, oninput, and onkeydown to avoid conflicts with the custom input handler
// see: https://github.com/chakra-ui/zag/blob/main/packages/machines/date-picker/src/date-picker.connect.ts#L757
// and: https://github.com/chakra-ui/zag/blob/main/packages/machines/date-picker/src/date-picker.connect.ts#L791
// and: https://github.com/chakra-ui/zag/blob/main/packages/machines/date-picker/src/date-picker.connect.ts#L770
const inputProps = $derived(
  omit(api.getInputProps(), [
    'type',
    'value',
    'onbeforeinput',
    'oninput',
    'onkeydown',
  ])
);

const positionerProps = $derived.by(() => {
  const props = api.getPositionerProps();
  const { style } = props;

  if (!style) {
    return props;
  }

  const cssProps: Record<string, string> = {};
  for (const declaration of style.split(';')) {
    const [prop, val] = declaration.split(':').map((rule) => rule.trim());
    if (prop && val) {
      cssProps[prop] = val;
    }
  }

  cssProps['z-index'] = '1000';

  const modifiedStyle = Object.entries(cssProps)
    .map(([prop, val]) => `${prop}: ${val}`)
    .join(';');

  return {
    ...props,
    style: modifiedStyle,
  };
});

const handleChange = (input: string | undefined): boolean => {
  if (input === value) {
    return false;
  }

  if (!input) {
    onChange({ type: 'undefined', value: undefined, date: undefined });
    value = undefined;
    return false;
  }

  const isRelativeTime = parseRelativeTime(input);
  if (isRelativeTime) {
    onChange({ type: 'relative', value: input, date: isRelativeTime.toDate() });
    value = input;
  } else {
    const result = dateFromDateValueString(input);
    if (!result.success) {
      currentError = result.error;
      return false;
    }

    onChange({
      type: 'absolute',
      value: input,
      date: result.date,
    });
  }

  return true;
};

const handleInput = (
  event: Event & {
    currentTarget: EventTarget & HTMLInputElement;
  }
) =>
  service.send({
    type: 'INPUT.CHANGE',
    value: (event.target as HTMLInputElement).value,
    index: inputProps['data-index'],
  });

const handleKeyDown = (
  event: KeyboardEvent & {
    currentTarget: EventTarget & HTMLInputElement;
  }
) => {
  if (event.defaultPrevented) return;
  if (disabled) return;
  if (event.key === 'Enter') {
    if (api.isUnavailable(api.focusedValue)) return;
    if (event.currentTarget.value.trim() === '') return;
    event.preventDefault();
    const changed = handleChange(event.currentTarget.value);
    service.send({
      type: 'INPUT.ENTER',
      value: event.currentTarget.value,
      index: inputProps['data-index'],
    });
    if (changed) {
      applyTimeFilter();
    }
  }
};

const handleDayClick = (input: DateValue) => {
  const next = getDateValueString(input, timezone);
  handleChange(next);
  service.send({
    type: 'CELL.CLICK',
    cell: 'day',
    value: input,
  });
};
</script>

<div
  {...api.getControlProps()}
  class="flex w-full gap-1"
>
  <RelativeTimeInput
    {...inputProps}
    {value}
    state={error ? InputStates.ERROR : InputStates.NONE}
    onchange={(
      event: Event & {
        currentTarget: EventTarget & HTMLInputElement;
      }
    ) => {
      event.preventDefault();
      handleChange(event.currentTarget.value);
    }}
    oninput={handleInput}
    onkeydown={handleKeyDown}
  />
  <button
    class="border-light bg-light text-gray-6 hover:border-medium hover:bg-medium active:bg-gray-2 flex min-h-[30px] w-[30px] min-w-[30px] items-center justify-center gap-1.5 border whitespace-nowrap select-none"
    {...api.getTriggerProps()}><Icon name="calendar-blank" /></button
  >
</div>
{#if currentError}
  <p class="text-danger-dark text-xs">{currentError}</p>
{/if}

<div
  use:portal
  {...positionerProps}
>
  <div
    {...api.getContentProps()}
    class="text-subtle-1 flex w-[240px] justify-center border border-[#D7D7D9] bg-white pb-2 text-sm shadow-sm"
  >
    <!-- Day View -->
    <div hidden={api.view !== 'day'}>
      <div
        class="flex h-[46px] py-2"
        {...api.getViewControlProps({ view: 'year' })}
      >
        <RelativeTimeIconButton
          icon="chevron-left"
          label="Previous"
          variant="ghost"
          {...api.getPrevTriggerProps()}
        />
        <div
          class="flex grow items-center justify-center text-sm font-semibold"
        >
          {api.visibleRangeText.start}
        </div>
        <RelativeTimeIconButton
          icon="chevron-right"
          label="Next"
          variant="ghost"
          {...api.getNextTriggerProps()}
        />
      </div>

      <table {...api.getTableProps({ view: 'day' })}>
        <thead {...api.getTableHeaderProps({ view: 'day' })}>
          <tr {...api.getTableRowProps({ view: 'day' })}>
            {#each api.weekDays as day (day.value.toString())}
              <th
                class="h-[32px] w-[32px]"
                scope="col"
                aria-label={day.long}>{day.narrow}</th
              >
            {/each}
          </tr>
        </thead>
        <tbody {...api.getTableBodyProps({ view: 'day' })}>
          {#each api.weeks as week, i (i)}
            <tr {...api.getTableRowProps({ view: 'day' })}>
              {#each week as item (item.day)}
                {@const cellState = api.getDayTableCellState({ value: item })}
                <td
                  class=""
                  {...api.getDayTableCellProps({ value: item })}
                >
                  {#if cellState.disabled}
                    <!-- don't show anything -->
                  {:else}
                    <div
                      class={[
                        'bg-opacity-50 flex h-[32px] w-[32px] items-center justify-center gap-10 rounded-[3px]',
                        {
                          'bg-gray-3 text-default font-semibold':
                            cellState.selected,
                          'text-default font-semibold': cellState.today,
                          'hover:cursor-pointer hover:bg-[#F0F0F0]':
                            !cellState.unavailable,
                          'text-disabled-dark rounded-none':
                            cellState.unavailable,
                        },
                      ]}
                      {...api.getDayTableCellTriggerProps({ value: item })}
                      onclick={(event) => {
                        if (event.defaultPrevented) return;
                        if (!cellState.selectable) return;
                        event.preventDefault();
                        handleDayClick(item);
                      }}
                    >
                      {item.day}
                    </div>
                  {/if}
                </td>
              {/each}
            </tr>
          {/each}
        </tbody>
      </table>
    </div>
  </div>
</div>
