<!--
  @component

  The badge is often used to display status information.

  ```svelte
  <Badge
    variant='green'
    label='Active'
  />
  ```
-->
<script lang="ts">
import type { ClassValue } from 'svelte/elements';

import { Icon, type IconName } from '../icon';
import Progress from '../progress/progress.svelte';
import type { BadgeVariantType } from './variants';

interface Props {
  /** The badge text. */
  label: string;

  /** The color theme of the badge. */
  variant?: BadgeVariantType;

  /** An optional icon to show in the badge. */
  icon?: IconName;

  /** Additional CSS classes to pass to the badge. */
  cx?: ClassValue;
}

const {
  label = '',
  variant = 'inactive',
  icon,
  cx: extraClasses = '',
}: Props = $props();

const TEXT_COLORS = {
  success: 'text-success-dark',
  warning: 'text-warning-dark',
  danger: 'text-danger-dark',
  inactive: 'text-default',
  pending: 'text-[#7c2fca]',
  neutral: 'text-info-dark',
  progress: 'text-info-dark',
} as const;

const iconColor = $derived(TEXT_COLORS[variant]);
</script>

<small
  class={[
    'inline-flex items-center gap-1 rounded-full border px-2.5 py-0.5 text-xs',
    {
      [`border-success-medium bg-success-light ${TEXT_COLORS.success}`]:
        variant === 'success',
      [`border-warning-medium bg-warning-light ${TEXT_COLORS.warning}`]:
        variant === 'warning',
      [`border-danger-medium bg-danger-light ${TEXT_COLORS.danger}`]:
        variant === 'danger',
      [`border-[#d3c1f6] bg-[#f5ebff] ${TEXT_COLORS.pending}`]:
        variant === 'pending',
      [`border-medium bg-light ${TEXT_COLORS.inactive}`]:
        variant === 'inactive',
      [`border-info-medium bg-info-light ${TEXT_COLORS.neutral}`]:
        variant === 'neutral' || variant === 'progress',
      'pl-1.5': variant === 'progress' || icon,
    },
    extraClasses,
  ]}
>
  {#if variant === 'progress'}
    <Progress customColor="info-dark" />
  {:else if icon}
    <Icon
      name={icon}
      size="xs"
      cx={iconColor}
    />
  {/if}
  {label}
</small>
