<script context="module"></script>

<script>
	import { BROWSER } from 'esm-env'
	import { beforeUpdate } from 'svelte'
	import InternalPaneDraggable from '../internal/InternalPaneDraggable.svelte'
	import InternalPaneFixed from '../internal/InternalPaneFixed.svelte'
	import InternalPaneInline from '../internal/InternalPaneInline.svelte'
	import { removeKeys } from '../utils.js'
	export let expanded = void 0
	export let position = void 0
	export let width = void 0
	export let tpPane = void 0
	export let x = void 0
	export let y = void 0
	beforeUpdate(() => {
		if ($$props.position !== 'inline' && $$props.position !== 'fixed') {
			return
		}
		x = $$props.x
		y = $$props.y
		width = $$props.width
		expanded = $$props.expanded
	})
</script>

<!-- Only prerender inline panes, because fixed / absolute positioned objects don't affect layout
-->
{#if position === undefined || position === 'draggable'}
	{#if BROWSER}
		<InternalPaneDraggable bind:expanded bind:tpPane bind:width bind:x bind:y {...$$restProps}>
			<slot></slot>
		</InternalPaneDraggable>
	{:else}
		<div style:display="none">
			<slot></slot>
		</div>
	{/if}
{:else if position === 'inline'}
	<InternalPaneInline
		{width}
		bind:expanded
		bind:tpPane
		{...removeKeys($$restProps, 'storePositionLocally')}
	>
		<slot></slot>
	</InternalPaneInline>
{:else if position === 'fixed'}
	{#if BROWSER}
		<InternalPaneFixed {width} bind:expanded bind:tpPane bind:x bind:y {...$$restProps}>
			<slot></slot>
		</InternalPaneFixed>
	{:else}
		<div style:display="none">
			<slot></slot>
		</div>
	{/if}
{/if}
