<!--
@component

For numeric user inputs.

```svelte
<NumericInput type="integer" on:input={onInput} />
```
-->
<svelte:options immutable />

<script lang="ts">
import type { ClassValue } from 'svelte/elements';

import Input from './input.svelte';
import type { NumericInputTypes } from './numeric-input-types';

/** The input type */
export let type: NumericInputTypes | undefined = 'number';

/** The value of the input, if any. */
export let value: number | undefined = undefined;

/** The amount to increment/decrement when using the up/down arrows. */
export let step: number | 'any' = 'any';

/** The HTML input element. */
export let input: HTMLInputElement | undefined = undefined;

/** Additional CSS classes to pass to the input. */
let extraClasses: ClassValue = '';
export { extraClasses as cx };

$: isNumber = type === 'number';
$: integerStep = step === 'any' ? 1 : step;
</script>

<Input
  type="number"
  cx={extraClasses}
  step={isNumber ? step : integerStep}
  placeholder={$$restProps.placeholder ?? 0}
  {...$$restProps}
  bind:value
  bind:input
  on:input
  on:change
  on:blur
  on:keydown
/>
