<!--
@component

For displaying keyboard shortcut indicators.

```svelte
<Kbd>S</Kbd>
```
-->

<script lang="ts">
import type { Snippet } from 'svelte';
import type { ClassValue } from 'svelte/elements';

interface Props {
  /** Additional CSS classes to pass to the kbd element. */
  cx?: ClassValue;
  /** Background style. Use 'dark' when placed on a dark background. */
  variant?: 'light' | 'dark';
  /** The content to display inside the kbd element. */
  children: Snippet;
}

const { cx, variant = 'light', children }: Props = $props();
</script>

<kbd
  class={[
    'pointer-events-none inline-flex h-4 min-w-4 items-center justify-center rounded-xs px-0.5 pt-px font-sans text-[11px] select-none',
    variant === 'dark'
      ? 'border border-white/20 text-white/60'
      : 'text-subtle-2 border mix-blend-multiply',
    cx,
  ]}
>
  {@render children()}
</kbd>
