<svelte:options />

<script lang="ts">
import { IconButton } from './button';
import { clickOutside } from './click-outside';

interface Props {
  /** Whether the modal is open. */
  isOpen: boolean;

  /** The variant of the modal. */
  variant?: 'small' | 'medium' | 'fit' | 'full';

  /** Accessible role of the modal. */
  role?: 'dialog' | 'alertdialog';

  /** Close event handler. */
  onClose: () => void;
}

const { isOpen, variant, role = 'dialog', onClose }: Props = $props();
const uniqueID: string = $props.id();
const headingID = $derived(`modal-heading-${uniqueID}`);
const descriptionID = $derived(`modal-description-${uniqueID}`);

const handleEscapePress = (event: KeyboardEvent) => {
  if (event.key === 'Escape') {
    event.preventDefault();
    onClose();
  }
};

$effect.pre(() => {
  if (typeof document !== 'undefined') {
    document.body.classList.toggle('overflow-hidden', isOpen);
  }

  return () => document.body.classList.remove('overflow-hidden');
});
</script>

<svelte:window on:keydown={isOpen ? handleEscapePress : undefined} />

{#if isOpen}
  <div
    class="fixed top-0 left-0 z-50 flex h-full w-full items-center justify-center bg-black/40"
    {role}
    aria-modal="true"
    aria-labelledby={headingID}
    aria-describedby={descriptionID}
  >
    <div
      use:clickOutside={onClose}
      class={[
        'border-medium relative min-w-[400px] border bg-white p-6 shadow-sm',
        {
          'max-h-[400px] max-w-[480px]': variant === undefined,
          'max-h-[600px] max-w-[800px]': variant === 'medium',
          'max-h-[320px] max-w-[400px]': variant === 'small',
          'h-full w-full': variant === 'full',
          // no max size for variant === 'fit'. Sized from content.
          'overflow-y-auto': true,
        },
      ]}
    >
      <IconButton
        cx="text-gray-6 absolute top-4 right-4"
        icon="close"
        label="Close modal"
        on:click={onClose}
      />

      <!-- TODO(mc, 2025-04-04): update to snippets -->
      <!-- svelte-ignore slot_element_deprecated -->
      <div class="flex min-h-full flex-col gap-2">
        <h2
          id={headingID}
          class="text-default pr-12 text-lg font-semibold"
        >
          <slot name="title" />
        </h2>

        <div
          id={descriptionID}
          class="text-subtle-1 text-sm"
        >
          <slot name="message" />
        </div>

        <div class="flex grow"><slot /></div>

        <div class="mt-6 flex justify-end gap-2">
          <slot name="tertiary" />
          <slot name="secondary" />
          <slot name="primary" />
        </div>
      </div>
    </div>
  </div>
{/if}
