<!--
@component

A clickable element that allows the user to navigate to another page or area.

```svelte
  <Tab
    title='The first tab'
    href="#first"
    selected
  />
```
-->
<script lang="ts">
import type { Snippet } from 'svelte';
import type { ClassValue } from 'svelte/elements';

import { Icon, type IconName } from './icon';
import { useTabsBarContext } from './tabs-bar.svelte';

interface Props {
  /** Additional CSS classes to apply to the tab element */
  class?: ClassValue;
  /** URL to navigate to when tab is clicked. If provided, renders as <a>; if not, renders as <button> */
  href?: string;
  /** Whether this tab is currently selected */
  selected?: boolean;
  /** Callback function to execute when tab is select */
  selectTab?: VoidFunction;
  /** Text content to display in the tab */
  title: string;
  /** Unique identifier for the tab element. Used with aria-labelledby if a corresponding tabpanel exists */
  id?: string;
  /** ID of the tabpanel this tab controls, if one exists. Used for aria-controls attribute */
  controls?: string;
  /** Snippet used to display additional information next to a tab */
  detail?: Snippet;
  /** Icon to put next to text */
  icon?: IconName;
}

const {
  class: extraClasses = '',
  href,
  selected = false,
  selectTab,
  title,
  id,
  controls,
  detail,
  icon = undefined,
}: Props = $props();

const variant = useTabsBarContext();

const handleClick = () => {
  if (!selected) {
    selectTab?.();
  }
};

const handleKeydown = (event: KeyboardEvent) => {
  if (!selected && ['Enter', 'Space'].includes(event.key)) {
    selectTab?.();
  }
};
</script>

<svelte:element
  this={href ? 'a' : 'button'}
  {id}
  role="tab"
  {href}
  aria-selected={selected}
  aria-controls={controls}
  tabindex={0}
  class={[
    // All tabs
    'text-sm',
    'hover:bg-ghost-light',
    'focus-visible:bg-ghost-light',
    'active:bg-ghost-medium active:text-default',
    { 'font-semibold': selected },

    // Primary tabs
    variant.current === 'primary' && [
      'font-roboto-mono rounded-sm px-3 py-1.5 text-[13px] tracking-wider uppercase',
      'hover:bg-ghost-light',
      'focus-visible:bg-ghost-light',
      { 'text-subtle-2': !selected },
    ],

    // Secondary tabs
    variant.current === 'secondary' && [
      'rounded px-2 py-1',
      { 'text-subtle-2': !selected },
    ],

    // Underline variant
    variant.current === 'underline' && [
      'border-b-[1.5px] pb-2.5',
      'hover:text-subtle-1 hover:!bg-transparent',
      selected ? 'border-gray-9 relative z-10 -mb-px' : 'border-transparent',
      { 'text-subtle-2': !selected },
    ],

    // Custom classes
    extraClasses,
  ]}
  {...href
    ? {}
    : {
        onclick: handleClick,
        onkeydown: handleKeydown,
      }}
>
  <div class="flex items-center gap-1.5">
    {#if icon}
      <Icon
        name={icon}
        cx={selected ? 'text-gray-8' : 'text-gray-6'}
      />
    {/if}
    <!-- Due to some weird CSS behavior from flex, we need to use first-letter:capitalize here. -->
    <!-- If you know a cleaner way to fix, by all means, go forth! -->
    <span class="first-letter:capitalize">
      {title}
    </span>
    {@render detail?.()}
  </div>
</svelte:element>
