<script lang="ts">
import type { Snippet } from 'svelte';
import type { ClassValue } from 'svelte/elements';
import { connect, machine } from '@zag-js/collapsible';
import { normalizeProps, useMachine } from '@zag-js/svelte';

interface Props {
  trigger: Snippet<[{ isOpen: boolean }]>;
  content: Snippet;
  class?: ClassValue;
  triggerClass?: ClassValue;
  contentClass?: ClassValue;
  open?: boolean;
}

let {
  trigger,
  content,
  class: extraClasses,
  triggerClass,
  contentClass,
  open = $bindable(false),
}: Props = $props();
const id = $props.id();

const service = useMachine(machine, {
  id,
  get open() {
    return open;
  },
  onOpenChange: (event) => (open = event.open),
});

const api = $derived(connect(service, normalizeProps));
</script>

<div
  {...api.getRootProps()}
  class={extraClasses}
>
  <button
    {...api.getTriggerProps()}
    class={triggerClass}
  >
    {@render trigger({ isOpen: open })}
  </button>
  <div
    {...api.getContentProps()}
    class={contentClass}
    role="region"
  >
    {@render content()}
  </div>
</div>

<style>
@keyframes expand {
  from {
    height: 0;
  }
  to {
    height: var(--height);
  }
}

@keyframes collapse {
  from {
    height: var(--height);
  }
  to {
    height: 0;
  }
}

[data-scope='collapsible'][data-part='content'] {
  overflow: hidden;
}

[data-scope='collapsible'][data-part='content'][data-state='open'] {
  animation: expand var(--transition-duration, 150ms)
    var(--transition-easing, cubic-bezier(0, 0, 0.38, 0.9));
}

[data-scope='collapsible'][data-part='content'][data-state='closed'] {
  animation: collapse var(--transition-duration, 150ms)
    var(--transition-easing, cubic-bezier(0, 0, 0.38, 0.9));
}
</style>
