<!--
@component

For rendering readonly blocks of code. Uses `highlight.js` for syntax highlighting:

https://highlightjs.org/

```svelte
<CodeSnippet language="json" code="{ myThing: true }">
    <svelte:fragment slot="caption">This text captions the code snippet.</svelte:fragment>
</CodeSnippet>
```
-->

<script lang="ts">
import 'highlight.js/styles/github.css';

import type { ClassValue } from 'svelte/elements';

import { IconButton } from './button';
import { type CodeSnippetCopyState, COPY_STATES } from './code-snippet';
import { highlightCode } from './highlight-code';
import { useTimeout } from './use-timeout';

/** Additional CSS classes to pass to the aside. */
interface Props {
  /**
   * The language to use for syntax highlighting. Must be a language supported by
   * highlight.js: https://highlightjs.org/
   */
  language: string;
  /**
   * The code to render in the code-snippet.
   */
  code: string;
  /**
   * Whether or not to show a copy-to-clipboard button.
   */
  showCopyButton?: boolean;
  cx?: ClassValue;
  caption?: import('svelte').Snippet;
  onCopy?: (details: { succeeded: boolean; message: string }) => void;

  /**
   * Whether or not to wrap lines.
   */
  wrapLines?: boolean;
}

const {
  language,
  code,
  showCopyButton = true,
  cx: extraClasses = '',
  caption,
  onCopy,
  wrapLines = false,
}: Props = $props();

const { set: setCopyTimeout } = useTimeout();

let copyState = $state('copy' as CodeSnippetCopyState);

const copyToClipboard = async () => {
  try {
    await navigator.clipboard.writeText(code);
    copyState = 'copied';

    onCopy?.({
      succeeded: true,
      message: 'Successfully copied snippet to the clipboard',
    });
  } catch {
    copyState = 'failed';

    onCopy?.({
      succeeded: false,
      message: 'Failed to copy snippet to the clipboard',
    });
  }

  setCopyTimeout(() => {
    copyState = 'copy';
  }, 2000);
};
</script>

<figure class={['flex flex-col gap-2', extraClasses]}>
  {#if caption}
    <figcaption>{@render caption?.()}</figcaption>
  {/if}

  <div class="bg-light relative flex h-full grow gap-x-4 p-1 pr-0 text-xs">
    <!-- The formatting here is intentional to preserve the formatting of `code` -->
    {#key code}
      <pre
        class="flex-1 overflow-x-auto pr-12!"
        use:highlightCode><code
          class="language-{language} {wrapLines ? 'text-wrap' : ''}"
          style="background: transparent;">{code}</code
        ></pre>
    {/key}

    {#if showCopyButton}
      <IconButton
        variant="secondary"
        cx="text-gray-6 absolute top-2.5 right-2.5"
        icon={COPY_STATES[copyState].icon}
        label={COPY_STATES[copyState].label}
        on:click={copyToClipboard}
        on:keyup={copyToClipboard}
      />
    {/if}
  </div>
</figure>
