export const getDecimals = (value = '', decimalDigits = 0) => {
    return Math.max(value.includes('.') ? value.length - value.indexOf('.') - 1 : 0, decimalDigits);
};
export const parseNumericInputValue = (value = '', type = 'number') => type === 'number' ? Number.parseFloat(value) : Number.parseInt(value, 10);
