<script lang="ts">
import type { ClassValue } from 'svelte/elements';

import { Icon, type IconName } from '../icon';
import { type InputState, InputStates } from '../input';

export let value: string | undefined;
export let menuId: string;
export let isOpen: boolean;
export let isFocused: boolean | undefined = undefined;
export let disabled = false;
export let state: InputState = InputStates.NONE;
export let containerElement: HTMLDivElement | undefined = undefined;
export let inputElement: HTMLInputElement | undefined = undefined;
export let icon: IconName | undefined = undefined;

/** Optional id used in parent label `for` attribute */
export let id: string | undefined = undefined;

/** Additional CSS classes to pass to the input. */
let extraClasses: ClassValue = '';
export { extraClasses as cx };

$: isWarn = state === InputStates.WARN;
$: isError = state === InputStates.ERROR;

$: defaultClasses = !disabled &&
  !isError &&
  !isWarn && [
    'border-light bg-white group-hover/select-input:border-gray-6',
    {
      'focus-within:border-gray-9': isFocused !== false,
    },
  ];

$: disabledClasses = disabled && [
  'cursor-not-allowed border-disabled-light bg-disabled-light text-disabled-dark',
  { 'focus-within:border-disabled-dark': isFocused !== false },
];

$: warnClasses = isWarn &&
  !disabled && [
    'border-warning-bright bg-white group-hover/select-input:outline-[1.5px] group-hover/select-input:-outline-offset-1 group-hover/select-input:outline-warning-bright',
    {
      'focus-within:outline-[1.5px] focus-within:-outline-offset-1 focus-within:outline-warning-bright':
        isFocused !== false,
    },
  ];

$: errorClasses = isError &&
  !disabled && [
    'border-danger-dark bg-white group-hover/select-input:outline-[1.5px] group-hover/select-input:-outline-offset-1 group-hover/select-input:outline-danger-dark',
    {
      'focus-within:outline-[1.5px] focus-within:-outline-offset-1 focus-within:outline-danger-dark':
        isFocused !== false,
    },
  ];
</script>

<div
  bind:this={containerElement}
  class={[
    'group/select-input relative flex h-7.5 w-full min-w-0 border',
    defaultClasses,
    disabledClasses,
    warnClasses,
    errorClasses,
    extraClasses,
  ]}
>
  <input
    bind:value
    bind:this={inputElement}
    {id}
    role="combobox"
    readonly={disabled ? true : undefined}
    aria-controls={menuId}
    aria-expanded={isOpen}
    aria-disabled={disabled ? true : undefined}
    aria-invalid={isError}
    type="text"
    class={[
      'min-w-0 grow appearance-none truncate py-1.5 pr-1 pl-2 text-xs leading-tight outline-none',
      // We want the native select to include the icon so we need absolute positioning and this padding
      { 'pl-8': Boolean(icon) },
    ]}
    {...$$restProps}
    on:input
    on:keydown
    on:focus
    on:blur
    on:mousemove
  />
  <button
    class="flex items-center pr-1.5"
    type="button"
    tabindex="-1"
    aria-label="Toggle menu"
    aria-controls={menuId}
    aria-expanded={isOpen}
    on:click
    on:keydown
    on:mousedown|preventDefault
    on:pointerdown|preventDefault
  >
    {#if icon}
      <div>
        <Icon
          name={icon}
          cx="text-gray-6"
        />
      </div>
    {/if}
    <div class="transform">
      <Icon
        name="chevron-down"
        cx={['text-gray-6 transition-transform', { 'rotate-180': isOpen }]}
      />
    </div>
  </button>
</div>
