<!--
@component

For user triggered actions.

```svelte
<IconButton type="submit" variant="success" on:click={onClick} />
```
-->
<script lang="ts">
import { onMount } from 'svelte';
import type { ClassValue, HTMLButtonAttributes } from 'svelte/elements';
import { omit } from 'lodash-es';

import { Icon, type IconName } from '../icon';
import { preventHandler } from '../prevent-handler';
import Progress from '../progress/progress.svelte';

interface Props
  extends Omit<
    HTMLButtonAttributes,
    'aria-label' | 'aria-disabled' | 'onclickcapture'
  > {
  /** The icon shown in the button. */
  icon: IconName;
  /** aria-label text for accessibility */
  label: string;
  /** The communicated action type to the user. */
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost';
  /** Shows progress indicator. Determinite progress is a @TODO */
  progress?: 'indeterminate' | number | undefined;
  /**
   * Additional CSS classes to pass to the button.
   * @deprecated Use `class` instead.
   * @todo (dtcurrie 8/5/25): Remove `cx` in favor of `class`
   */
  cx?: ClassValue;
}

const {
  icon,
  label,
  disabled = false,
  type = 'button',
  variant = 'primary',
  progress = undefined,
  // eslint-disable-next-line @typescript-eslint/no-deprecated
  cx,
  class: extraClasses = '',
  ...rest
}: Props = $props();

const handleDisabled = $derived(preventHandler(Boolean(disabled)));

onMount(() => {
  if (cx && extraClasses) {
    // eslint-disable-next-line no-console
    console.warn(
      '`cx` and `class` cannot be used together. Use `class` instead.'
    );
  }
});

const buttonProps = $derived(
  omit(rest, ['aria-label', 'aria-disabled', 'onclickcapture'])
);
</script>

<button
  {type}
  aria-label={label}
  aria-disabled={disabled ? true : undefined}
  class={[
    'inline-flex size-7.5 items-center justify-center whitespace-nowrap select-none',
    {
      'text-gray-6': !disabled,
      'text-gray-4 cursor-not-allowed': disabled,
      'hover:border-medium hover:bg-medium hover:text-gray-7 active:bg-gray-2 active:text-gray-8':
        variant === 'primary' && !disabled,
      'text-default hover:bg-ghost-light active:border-ghost-medium active:bg-ghost-medium border border-transparent':
        variant === 'ghost' && !disabled,
      'border-light bg-light hover:border-medium hover:bg-medium active:border-medium active:bg-gray-2 border':
        variant === 'secondary' && !disabled,
      'hover:bg-danger-dark/10 hover:text-danger-dark active:text-danger-dark active:bg-[rgba(190,53,54,0.16)]':
        variant === 'danger' && !disabled,
    },
    cx,
    extraClasses,
  ]}
  onclickcapture={handleDisabled}
  {...buttonProps}
>
  {#if progress}
    <Progress variant={variant === 'danger' ? 'light' : 'dark'} />
  {:else}
    <Icon name={icon} />
  {/if}
</button>
