<script lang="ts">
import type { HTMLInputAttributes } from 'svelte/elements';
import { omit } from 'lodash-es';

import { Icon, type IconName } from '../icon';
import { type InputState, InputStates } from '../input/input-state';
import { preventHandler, preventKeyboardHandler } from '../prevent-handler';

/** Additional CSS classes to pass to the input. */
interface Props extends HTMLInputAttributes {
  /** The state of the input (info, warn, error, success), if any. */
  state?: InputState | undefined;
  /** The HTML input element. */
  input?: HTMLInputElement | undefined;
}

let {
  value = $bindable(''),
  readonly = false,
  disabled = false,
  state = InputStates.NONE,
  input = $bindable(undefined),
  class: extraClasses = '',
  ...rest
}: Props = $props();

const isInfo = $derived(state === InputStates.INFO);
const isWarn = $derived(state === InputStates.WARN);
const isError = $derived(state === InputStates.ERROR);
const isDisabled = $derived(disabled === true);
const isReadonly = $derived(readonly === true);
const isInputReadOnly = $derived(isDisabled || isReadonly);
const handleDisabled = $derived(preventHandler(isInputReadOnly));
const handleDisabledKeydown = $derived(preventKeyboardHandler(isInputReadOnly));
const attributes = $derived(
  omit(rest, [
    'value',
    'data-1p-ignore',
    'aria-disabled',
    'aria-invalid',
    'oninputcapture',
    'onchangecapture',
    'onkeydowncapture',
  ])
);

const icon = $derived(
  state
    ? (
        {
          [InputStates.INFO]: 'information',
          [InputStates.WARN]: 'alert',
          [InputStates.ERROR]: 'alert-circle',
        } as Record<InputState, IconName>
      )[state]
    : undefined
);

const defaultClasses = $derived(
  !disabled &&
    !readonly &&
    !isError &&
    'border-light bg-white hover:border-gray-6 focus:border-gray-9'
);

const readonlyClasses = $derived(
  readonly && 'bg-light focus:border-gray-9 border-transparent'
);

const disabledClasses = $derived(
  disabled &&
    'border-disabled-light focus:border-disabled-dark bg-disabled-light text-disabled-dark cursor-not-allowed select-none'
);

const errorClasses = $derived(
  isError &&
    'border-danger-dark focus:outline-danger-dark focus:outline-[1.5px] focus:-outline-offset-1'
);

const warningClasses = $derived(
  isWarn &&
    'border-warning-dark focus:outline-warning-dark focus:outline-[1.5px] focus:-outline-offset-1'
);
</script>

<div class="grow">
  <input
    bind:value
    bind:this={input}
    type="text"
    readonly={isInputReadOnly ? true : undefined}
    aria-disabled={disabled ? true : undefined}
    aria-invalid={isError ? true : undefined}
    class={[
      'text-default h-7.5 w-full appearance-none border px-2 py-1.5 text-xs leading-tight outline-none',
      defaultClasses,
      readonlyClasses,
      disabledClasses,
      errorClasses,
      extraClasses,
      warningClasses,
    ]}
    oninputcapture={handleDisabled}
    onchangecapture={handleDisabled}
    onkeydowncapture={handleDisabledKeydown}
    {...attributes}
  />

  {#if icon}
    <Icon
      cx={[
        'absolute top-1.5 right-2',
        {
          'text-info-dark': isInfo,
          'text-warning-bright': isWarn,
          'text-danger-dark': isError,
        },
      ]}
      name={icon}
    />
  {/if}
</div>
