<script
  lang="ts"
  generics="DataType extends ({[key: string]: unknown, variant?: TableRowVariant})"
>
import '@ag-grid-community/styles/ag-grid.css';
import '@ag-grid-community/styles/ag-theme-quartz.css';

import { onMount } from 'svelte';
import type { ClassValue } from 'svelte/elements';
import { ClientSideRowModelModule } from '@ag-grid-community/client-side-row-model';
import type { Module, RowClassRules } from '@ag-grid-community/core';
import {
  type ColDef,
  type ColGroupDef,
  createGrid,
  type GridApi,
  type GridOptions,
  type GridParams,
} from '@ag-grid-community/core';

import type { TableRowVariant } from './table/table-variant';

interface AGGridTableProps {
  /** Defines the columns to render. */
  columnDefs: (ColDef<DataType> | ColGroupDef<DataType>)[];
  /** Defines the rows to be rendered. */
  rowData: DataType[];
  /**
   * Modules to be registered directly with this grid instance.
   * If none is provided, `[ClientSideRowModelModule]` is used.
   *
   * @default [ClientSideRowModelModule]
   */
  modules?: Module[];
  /** AG-Grid table options. See: https://www.ag-grid.com/javascript-data-grid/grid-options/ */
  options?: Omit<GridOptions<DataType>, 'columnDefs' | 'rowData'>;
  /**
   * AG-Grid table params. This can be used to individually register AG Grid Modules to this grid.
   * @default {  modules: [ClientSideRowModelModule] }
   */
  params?: Omit<GridParams, 'modules'>;
  /** A CSS rule to set the height for the table. */
  height: string;
  /** Extra class names. */
  class?: ClassValue;
}

const {
  columnDefs,
  rowData,
  options = {},
  modules = [ClientSideRowModelModule],
  params,
  height,
  class: extraClasses,
}: AGGridTableProps = $props();

let grid: GridApi<DataType>;
let eGui: HTMLDivElement;

const rowClassRules = $derived({
  'border-red-100! bg-red-50! text-red-500!': ({ data }) =>
    data?.variant === 'error',
  'border-green-100! bg-green-50! text-green-700!': ({ data }) =>
    data?.variant === 'success',
  'bg-gray-50! text-gray-500!': ({ data }) => data?.variant === 'disabled',
  ...options.rowClassRules,
} as RowClassRules<DataType>);

$effect.pre(() => {
  const next = [...columnDefs];
  grid?.updateGridOptions({ columnDefs: next });
});

$effect.pre(() => {
  const next = [...rowData];
  grid?.updateGridOptions({ rowData: next });
});

$effect.pre(() => {
  grid?.updateGridOptions({
    ...options,
    rowClassRules,
  });
});

onMount(() => {
  grid = createGrid(
    eGui,
    { ...options, columnDefs, rowData, rowClassRules },
    { ...params, modules }
  );

  return () => grid?.destroy();
});
</script>

<div
  bind:this={eGui}
  style="height: {height};"
  class={['ag-theme-quartz rounded-none', extraClasses]}
></div>

<style>
.ag-theme-quartz {
  --ag-borders: none;
  --ag-border-color: var(--color-gray-3);
  --ag-font-family: var(--font-public-sans);
  --ag-header-foreground-color: var(--color-subtle-2);
  --ag-header-background-color: var(--color-gray-1);
  --ag-header-cell-hover-background-color: var(--color-ghost-light);
  --ag-header-cell-moving-background-color: var(--color-ghost-light);
  --ag-wrapper-border-radius: 0;
}
</style>
