<!--
@component

For users to choose only one of a predefined set of mutually exclusive options.

```svelte
<Radio
  name="options"
  options="['Opt 1', 'Opt 2', 'Opt 3']"
  selected="Opt 1"
/>
```
-->
<svelte:options immutable />

<script
  context="module"
  lang="ts"
>
export type { RadioOption } from './radio';
</script>

<script lang="ts">
import type { ClassValue } from 'svelte/elements';

import { Icon } from './icon';
import { Label } from './label';
import { preventHandler, preventKeyboardHandler } from './prevent-handler';
import type { RadioOption } from './radio';

type Options = (string | RadioOption)[];

/** The set of options that is available in the radio button. */
export let options: Options;

/** The name for the inputs in the fieldset of radio options. */
export let name: string;

/** The selected option on the radio button. */
export let selected: string | undefined = undefined;

/**  Whether or not the radio should render as disabled. */
export let disabled = false;

/** Whether or not the fieldset should render as required */
export let required = false;

/** Additional CSS classes to pass to the options. */
export let optionCX: ClassValue = '';

/** Layout direction of the options within the fieldset. */
export let direction: 'col' | 'row' = 'col';

/** Additional CSS classes to pass to the fieldset. */
let extraClasses: ClassValue = '';
export { extraClasses as cx };

let optionsInternal: RadioOption[] = [];

$: optionsInternal = options.map((option) =>
  typeof option === 'string' ? { label: option, value: option } : option
);
</script>

<fieldset
  aria-disabled={disabled ? true : undefined}
  class={[
    'flex gap-2',
    direction === 'row' ? 'flex-row' : 'flex-col',
    extraClasses,
  ]}
  {...$$restProps}
>
  {#if $$slots.legend}
    <legend
      class={[
        'text-subtle-1 mb-2 flex text-xs',
        {
          'after:text-danger-dark after:content-["*"]': required,
        },
      ]}
    >
      <slot name="legend" />
    </legend>
  {/if}

  {#each optionsInternal as { label, value, description, disabled: optionDisabled, icon, iconCX, labelCX, components, componentsProps, alwaysShowComponents, errorMessage } (label)}
    {@const isDisabled = disabled || (optionDisabled ?? false)}
    {@const isSelected = value === selected}
    {@const radioIcon = isSelected ? 'radiobox-marked' : 'radiobox-blank'}
    <div class={['flex flex-col gap-2', optionCX]}>
      <Label
        position="left"
        disabled={isDisabled}
        cx={[
          'cursor-pointer text-xs',
          {
            'text-subtle-1': !isSelected && !isDisabled,
            'text-disabled-dark cursor-not-allowed': isDisabled,
          },
        ]}
      >
        <div class="flex flex-col gap-2">
          <div class="flex">
            <input
              {name}
              {value}
              type="radio"
              class="peer appearance-none"
              checked={isSelected}
              readonly={isDisabled ? true : undefined}
              aria-disabled={isDisabled ? true : undefined}
              bind:group={selected}
              on:input
              on:input|capture={preventHandler(isDisabled)}
              on:click|capture={preventHandler(isDisabled)}
              on:keydown|capture={preventKeyboardHandler(isDisabled)}
            />
            <div>
              <Icon
                name={radioIcon}
                cx={[
                  {
                    'text-disabled-dark': isDisabled,
                    'text-gray-9': !isDisabled && isSelected,
                    'text-gray-6': !isDisabled && !isSelected,
                  },
                ]}
              />
            </div>
            <span class="pl-1.5">
              <span class="flex gap-1.5">
                {#if icon}
                  <Icon
                    cx={iconCX ?? 'text-gray-7'}
                    name={icon}
                  />
                {/if}
                <span
                  class={[
                    {
                      'font-semibold': isSelected,
                      'text-default': isSelected && !isDisabled && !labelCX,
                    },
                    labelCX,
                  ]}>{label}</span
                >
              </span>
              {#if description}
                <p class="text-subtle-2 mt-0.5">{description}</p>
              {/if}
            </span>
          </div>
          {#if components && (isSelected || alwaysShowComponents)}
            {#each components as component, i (component)}
              <div class="flex flex-col gap-1 pl-5 text-xs">
                {#if typeof component === 'string'}
                  {#if component === 'span'}
                    <span class={componentsProps?.[i]?.cx ?? ''}>
                      {componentsProps?.[i]?.text ?? ''}
                    </span>
                  {/if}
                {:else}
                  <svelte:component
                    this={component}
                    {...componentsProps?.[i]}
                  />
                {/if}
                {#if errorMessage && componentsProps?.[i]?.state === 'error'}
                  <span class="text-danger-dark">{errorMessage}</span>
                {/if}
              </div>
            {/each}
          {/if}
        </div>
      </Label>
    </div>
  {/each}
</fieldset>
