<div
  class={[
    'border-medium bg-light inline-flex gap-2.5 truncate rounded-full border px-2.5 py-px',
    isDisabled ? 'text-disabled' : 'text-default',
    cx,
  ]}
>
  {#each crumbs as crumb, index (index)}
    <small class="truncate text-xs">
      {crumb}
    </small>
    {#if index !== crumbs.length - 1}
      <div>
        <div
          class="border-medium -mt-0.5 h-[69%] w-px -rotate-30 border-l"
        ></div>
        <div
          class="border-medium -mt-0.5 h-[69%] w-px rotate-30 border-l"
        ></div>
      </div>
    {/if}
  {/each}
</div>
