<script lang="ts">
import { Progress } from './progress';
import { Tooltip } from './tooltip';

interface Props {
  label: string;
  variant: 'success' | 'warning' | 'danger' | 'inactive';
  tooltip?: string;
  /**
   * When true, the static colored dot is replaced by an animated
   * Progress (dots variant). Use for in-flight / transient states
   * like fetching or configuring.
   */
  loading?: boolean;
}

const { label, variant, tooltip, loading = false }: Props = $props();

const VARIANT_COLORS: Record<string, string> = {
  success: 'border-success-medium bg-success-light text-success-dark',
  warning: 'border-warning-medium bg-warning-light text-warning-dark',
  danger: 'border-danger-medium bg-danger-light text-danger-dark',
  inactive: 'border-light bg-light text-subtle-1',
};

const DOT_COLORS: Record<string, string> = {
  success: 'bg-success-dark',
  warning: 'bg-warning-bright',
  danger: 'bg-danger-dark',
  inactive: 'bg-gray-6',
};
</script>

<Tooltip
  let:tooltipID
  hoverDelayMS={500}
  state={tooltip ? undefined : 'invisible'}
>
  <span
    class={[
      'flex h-[22px] items-center gap-1.5 rounded border px-1.5 font-mono text-[11px] tracking-wider uppercase',
      VARIANT_COLORS[variant],
    ]}
    aria-describedby={tooltipID}
  >
    {#if loading}
      <Progress variant="dots" />
    {:else}
      <span class={['h-1.5 w-1.5 shrink-0 rounded-full', DOT_COLORS[variant]]}
      ></span>
    {/if}
    {label}
  </span>
  <p slot="description">{tooltip}</p>
</Tooltip>
