<!--
@component

A full-screen takeover dialog component.

```svelte
<Takeover {isOpen} onClose={handleClose}>
  <TakeoverHeader>
    <TakeoverTitle>Setup Wizard</TakeoverTitle>
    <TakeoverClose />
  </TakeoverHeader>
  Your content here
</Takeover>
```
-->
<script lang="ts">
import type { Snippet } from 'svelte';
import type { ClassValue } from 'svelte/elements';
import { connect, machine } from '@zag-js/dialog';
import { normalizeProps, portal, useMachine } from '@zag-js/svelte';

import { setTakeoverContext } from './takeover-context';

interface Props {
  isOpen?: boolean;
  onClose?: () => void;
  children?: Snippet;
  class?: ClassValue;
}

const { isOpen = false, onClose, children, class: className }: Props = $props();

const id = $props.id();
const service = useMachine(machine, {
  id,
  get open() {
    return isOpen;
  },
  onOpenChange(event) {
    if (event.open) {
      return;
    }

    onClose?.();
  },
});

const api = $derived(connect(service, normalizeProps));

setTakeoverContext({
  get api() {
    return api;
  },
  get onClose() {
    return onClose;
  },
});
</script>

{#if api.open}
  <div
    use:portal
    {...api.getBackdropProps()}
    class="fixed inset-0 z-1400 bg-white"
  ></div>
  <div
    use:portal
    {...api.getPositionerProps()}
    class="fixed inset-0 z-1400 h-screen w-screen"
  >
    <div
      {...api.getContentProps()}
      class={['h-screen w-screen bg-white', className]}
    >
      {@render children?.()}
    </div>
  </div>
{/if}
