<!--
@component

A nav container with optional variant: 'primary' | 'secondary' | 'underline'

```svelte
<TabsBar variant='secondary'>
  <Tab
    title='The first tab'
    href="#first"
    isSelected='true' 
  />
  <Tab
    title='The second tab'
    href="#second"
    isSelected='false' 
  />
  <Tab
    title='The third tab'
    href="#third"
    isSelected='false' 
  />
</TabsBar>
```
-->
<script
  module
  lang="ts"
>
type Variant = 'primary' | 'secondary' | 'underline';

import { getContext, setContext, type Snippet } from 'svelte';

export const CONTEXT_KEY = Symbol('tabs-bar-context');

interface Context {
  readonly current: Variant;
}

const provideTabsBarContext = (variant: () => Variant) => {
  setContext<Context>(CONTEXT_KEY, {
    get current() {
      return variant();
    },
  });
};

export const useTabsBarContext = (): Context => {
  return getContext(CONTEXT_KEY);
};
</script>

<script lang="ts">
import type { ClassValue } from 'svelte/elements';

interface Props {
  /** Accessible label for the tab list */
  'aria-label'?: string;
  /** ID of the element that labels this tab list */
  'aria-labelledby'?: string;
  /** The tab style variant */
  variant?: Variant;
  /** Additional CSS classes to apply to the nav element */
  class?: ClassValue;
  children?: Snippet;
}

const {
  'aria-label': ariaLabel,
  'aria-labelledby': ariaLabelledby,
  children,
  class: className = '',
  variant = 'primary',
}: Props = $props();

provideTabsBarContext(() => variant);
</script>

<div
  role="tablist"
  aria-label={ariaLabel}
  aria-labelledby={ariaLabelledby}
  aria-orientation="horizontal"
  class={[
    // Primary variant
    variant === 'primary' && [
      'flex min-h-10 flex-wrap items-center gap-2 sm:px-2',
    ],

    // Secondary variant
    variant === 'secondary' && ['flex min-h-10 flex-wrap items-center gap-4'],

    // Underline variant
    variant === 'underline' && ['flex gap-6 border-b'],

    // Custom classes
    className,
  ]}
>
  {@render children?.()}
</div>
